sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var env = new x_fed_day2_ops.Day2Env();
  if (!env.isTestMode()) {
    stepResult.setFailed('x_fed_day2_ops.test_mode must be true on a declared non-prod instance');
    return;
  }
  var sam = new x_fed_day2_ops.SamCorrelationClient();
  var v = sam.verifyJws('ATF-SAM-JWS-0001', 'canned-key');
  if (!v.ok) { stepResult.setFailed('test_mode verifyJws should return canned claims: ' + JSON.stringify(v)); return; }
  ['sam_request_id', 'requested_for', 'status'].forEach(function (k) {
    if (!v.claims[k]) stepResult.setFailed('canned JWS claims must carry ' + k + ' — the endpoint requires it');
  });
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  // Mirrors isApprovedStatus() in scripted-rest/sam_inbound_ritm.js.
  function isApprovedStatus(raw) {
    var st = ('' + (raw || '')).toLowerCase();
    return st === 'approved' || st === 'verified' || st === 'complete';
  }
  var refused = ['denied', 'pending', 'revoked', 'rejected', ''];
  for (var i = 0; i < refused.length; i++) {
    if (isApprovedStatus(refused[i])) {
      stepResult.setFailed('REGRESSION: a signed assertion with status "' + refused[i] +
                           '" would be treated as approved');
      return;
    }
  }
  // ...and the approved forms still pass, or the gate is simply broken shut.
  var accepted = ['approved', 'Approved', 'VERIFIED', 'complete'];
  for (var j = 0; j < accepted.length; j++) {
    if (!isApprovedStatus(accepted[j])) {
      stepResult.setFailed('status "' + accepted[j] + '" should be accepted');
      return;
    }
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  // Mirrors the subject binding in verifyWithSam()'s JWS branch.
  function subjectBinds(claims, pushedRequestedFor) {
    if (!claims.requested_for) return { ok: false, code: 'signature_subject_unbound' };
    if (('' + claims.requested_for).toLowerCase() !== ('' + pushedRequestedFor).toLowerCase())
      return { ok: false, code: 'subject_mismatch' };
    return { ok: true };
  }

  var signedForAlice = { requested_for: 'alice-0001', status: 'approved' };

  var redirected = subjectBinds(signedForAlice, 'bob-0002');
  if (redirected.ok || redirected.code !== 'subject_mismatch') {
    stepResult.setFailed('REGRESSION: a signature bound to alice-0001 was accepted for bob-0002');
    return;
  }

  // A signer that omits the subject leaves it caller-controlled: refuse.
  var unbound = subjectBinds({ status: 'approved' }, 'bob-0002');
  if (unbound.ok || unbound.code !== 'signature_subject_unbound') {
    stepResult.setFailed('REGRESSION: a claim set with no requested_for was accepted — the subject ' +
                         'would be unsigned and caller-asserted');
    return;
  }

  // Case-insensitive match on the same subject still verifies.
  if (!subjectBinds(signedForAlice, 'ALICE-0001').ok) {
    stepResult.setFailed('subject comparison should be case-insensitive, as on the pull-verify path');
    return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);
